def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 4:
        return 'C'

    opp_c = 0
    opp_d = 0
    my_d = 0
    consec_opp_d = 0
    consec_opp_c = 0
    for i in range(n):
        a, b = history[i]
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'D':
            my_d += 1

    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_opp_d += 1
        else:
            break
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            consec_opp_c += 1
        else:
            break

    opp_prev = history[-1][1]
    remaining = 100 - n

    win = history[-8:] if n >= 8 else history
    wc = 0
    for a, b in win:
        if b == 'C':
            wc += 1
    recent_c = wc
    recent_total = len(win)

    if opp_d == 0:
        if remaining <= 1:
            return 'D'
        if remaining <= 6 and n >= 20:
            return 'D'
        if n >= 30 and my_d == 0:
            return 'D'
        if n >= 12 and n % 9 == 0:
            return 'D'
        return 'C'

    if opp_d >= n - 1:
        if n % 13 == 0:
            return 'C'
        return 'D'

    if opp_d * 5 >= n * 4:
        if n % 7 == 0 and opp_prev == 'D':
            return 'C'
        return 'D'

    if remaining <= 2:
        if recent_c * 2 >= recent_total:
            return 'D'
        return 'D' if opp_prev == 'D' else 'C'

    if remaining <= 6:
        if recent_c * 3 >= recent_total * 2:
            return 'D'
        if opp_prev == 'D' and opp_d * 2 >= n:
            return 'D'
        if opp_prev == 'D':
            return 'C'
        return 'C'

    if remaining <= 12:
        if recent_c * 3 >= recent_total * 2 and n >= 12:
            return 'D'
        if opp_prev == 'D':
            if opp_d * 4 <= n:
                return 'C'
            return 'D'
        if opp_d * 3 >= n * 2:
            return 'D'
        return 'C'

    if consec_opp_d >= 4:
        return 'D'
    if consec_opp_d == 3:
        if opp_d * 4 <= n and rng.random() < 0.4:
            return 'C'
        return 'D'
    if consec_opp_d == 2:
        if opp_d * 5 <= n:
            return 'C'
        return 'D'
    if consec_opp_d == 1:
        if opp_d * 6 <= n:
            return 'C'
        if opp_d * 3 <= n and rng.random() < 0.4:
            return 'C'
        return 'D'

    if opp_d * 5 <= n:
        if n >= 20 and n % 11 == 0 and remaining > 15:
            return 'D'
        return 'C'

    if opp_d * 2 <= n:
        if n % 7 == 0 and remaining > 20:
            return 'D'
        return 'C'

    if opp_d * 5 <= n * 4:
        return 'C'

    return 'D'
